/**
 * One file, everything the database needs.
 *
 * `supabase db push` is the right way to apply this, but it needs the CLI and a
 * linked project. When neither is to hand — a fresh project, a borrowed laptop, a
 * phone — Supabase Studio has a SQL editor, and the honest answer to "what do I
 * paste?" should be one file rather than "four migrations, in order, and mind the
 * transaction".
 *
 * There is no seed to append: the database ships empty, and the catalogue is
 * whatever accounts publish into it.
 *
 *   node scripts/sql-bundle.mjs   →   supabase/setup.sql
 */

import { readFileSync, writeFileSync, readdirSync } from "node:fs";
import { join } from "node:path";

const root = process.cwd();
const migrations = readdirSync(join(root, "supabase/migrations"))
  .filter((name) => name.endsWith(".sql"))
  .sort();

const list = migrations.map((name, i) => `--   ${i + 1}. migrations/${name}`).join("\n");

const header = `-- CoolNasheed · supabase/setup.sql — the whole database
--
-- Generated by scripts/sql-bundle.mjs — do not edit by hand.
-- In the order it must be applied:
--
${list}
--
-- Two ways to run it:
--
--   supabase link --project-ref <ref> && supabase db push
--
--   …or open Supabase Studio → SQL Editor → New query, paste this file, and Run.
--      It is safe to run twice: every statement is \`if not exists\` / \`or replace\`.
--
-- The database it builds is empty. There is no catalogue to seed — nasheeds are
-- published by accounts, from the Studio page, and they live in Storage.
`;

const parts = [header];
for (const name of migrations) {
  parts.push(`\n/* ================================================================ ${name} */\n`);
  parts.push(readFileSync(join(root, "supabase/migrations", name), "utf8").trimEnd());
  parts.push("\n");
}
const bundle = parts.join("\n");

const outPath = join(root, "supabase/setup.sql");
writeFileSync(outPath, bundle);

const kb = (text) => `${(Buffer.byteLength(text) / 1024).toFixed(0)} KB`;
console.log(`supabase/setup.sql — ${migrations.length} migrations, ${kb(bundle)}`);
